008      public static double EmptyMinutes(IEnumerable<Reading> history, int maxGapMinutes)
009      {
010          var readings = history.OrderBy(x => x.At).DistinctBy(x => x.At).ToList();
011          double total = 0;
012          for (int i = 1; i < readings.Count; i++)
013          {
014              var gap = (readings[i].At - readings[i - 1].At).TotalMinutes;
015              if (gap > 0 && gap <= maxGapMinutes && readings[i - 1].Count == 0 && readings[i].Count == 0) total += gap;
016          }
017          return Math.Round(total, 1);
